class Solution {
  public int[] getSumAbsoluteDifferences(int[] nums) {
    int n = nums.length;
    long total = 0;
    for (int x : nums) total += x;
    long left = 0;
    int[] ans = new int[n];
    for (int i = 0; i < n; i++) {
      long right = total - left - nums[i];
      ans[i] = (int) (nums[i] * (long) i - left + right - nums[i] * (long) (n - i - 1));
      left += nums[i];
    }
    return ans;
  }
}
